insert into public.profile (id, name, headline, positioning, summary, email, linkedin, instagram, github, location, resume_url) values (1, 'Anushka Nath', 'Serial blue-sky thinker, trying her hand at building.', 'Learning a bit of everything and trusting the dots will connect. You only ever see them looking backwards.', 'Owned a ₹3 Cr audit & advisory portfolio across 65+ engagements, then started building: live apps, an AI app for dance studios, and a leadership role in the AI & Analytics Club. Drawn to structuring fast-scaling B2B businesses and leading 0-to-1 initiatives in tech.', 'nath.anushka26@gmail.com', 'https://www.linkedin.com/in/anushkanath/', 'https://www.instagram.com/uhhhnushka_0.o/', 'https://github.com/anushkanath20032008', 'Gurgaon / Bengaluru / Kochi, India', null);
