insert into public.entries (id, folder_slug, slug, title, org, role, period, location, kind, status, sort, body) values ('crowe', 'work-experience', 'crowe-advisory', 'Project Coordinator → Customer Lifecycle Manager', 'Crowe Advisory Services (India) LLP', 'Project Coordinator', 'Jul''24 – Jun''26', 'Kochi, Kerala', 'work', null, 1, '{"images":[{"src":"img/crowe-award.jpg","alt":"Anushka receiving a thank-you plaque from the Crowe team","caption":"Thank-you plaque from the Crowe team","pos":"30% 60%"}],"summary":"Cybersecurity and assurance practice (VAPT, architecture and code review, digital forensics, SOC 1/2, ISAE 3000/3402). The practice scaled 3x in engagement volume while I moved from coordinating projects to managing the customer lifecycle.","gap":"Ad-hoc quality practices, no real-time view of revenue, utilisation or profitability, and a profitability leak in Vulnerability Assessment.","system":"Modelled executive dashboards from scratch, designed a quality management system to meet an international standard mandate, and rebuilt delivery workflows and capacity planning.","result":"₹3 Cr portfolio, 65+ engagements, 30% faster turnaround, 1.5x resource utilisation, ~26% lead conversion.","metrics":["₹3 Cr portfolio","65+ engagements","30% faster turnaround","1.5x utilisation","~26% lead conversion"]}'::jsonb);
insert into public.entries (id, folder_slug, slug, title, org, role, period, location, kind, status, sort, body) values ('stepping-stone', 'work-experience', 'the-stepping-stone', 'The Stepping Stone (field notes)', 'Essay', null, 'Autumn 2024', null, 'writing', null, 2, '{"summary":"Observations on high-velocity execution and accountability: what cross-functional operations looks like behind the scenes.","bullets":["You will never have as much authority as you have responsibility. The only currency that works is rapport.","Authority vs. responsibility: you earn attention by showing up early enough, often enough, and being useful enough that people choose to listen.","Problem solver and operational leverage: you absorb what has no owner, and if you can defend your reasoning you can move leadership.","Stepping stone, not destination: being in every room is access, and what you do with it is up to you."],"tags":["operations","strategy","field notes"]}'::jsonb);
insert into public.entries (id, folder_slug, slug, title, org, role, period, location, kind, status, sort, body) values ('choreostudio', 'builds', 'choreostudio', 'ChoreoStudio', null, 'Founder & Builder', '2026', null, 'build', 'live', 1, '{"summary":"An AI-assisted operations app for independent dance studios in India: students, guardians, batches, attendance, individual fee plans, a payments ledger, and WhatsApp reminders, with a simple link for families.","gap":"Independent dance studios run on WhatsApp groups and notebooks, so fees, attendance and reminders slip.","system":"A scrapbook-style studio app: batches describe where a student dances, fee plans describe what each student owes, and families see classes, attendance and balance from one link.","result":"Live at choreostudio.live with a free first month for studios.","links":[{"label":"Open ChoreoStudio","url":"https://choreostudio.live"}],"images":[{"src":"img/choreo-hero.png","alt":"ChoreoStudio landing page: Less chasing, more dancing","caption":"The landing page","pos":"top"},{"src":"img/choreo-tall.png","alt":"ChoreoStudio fee estimate calculator","caption":"Fee calculator for studio owners","pos":"50% 24%"}],"tags":["AI app","dance studios","live"]}'::jsonb);
insert into public.entries (id, folder_slug, slug, title, org, role, period, location, kind, status, sort, body) values ('homebody', 'builds', 'homebody', 'HomeBody', null, 'Designer & Builder', null, null, 'build', 'live', 2, '{"summary":"An au-pair inspired matching platform: verified students get affordable accommodation, and urban families get flexible domestic support.","gap":"Acute shortage of affordable, safe student housing in metros, alongside families struggling to find trustworthy household help.","system":"A two-sided matching ecosystem where students exchange structured help for a stay with vetted host families, with mutual verification and schedule compatibility.","result":"Live MVP with onboarding, compatibility filtering and profile verification.","links":[{"label":"Open HomeBody","url":"https://homebodyindia.lovable.app"}],"tags":["marketplace","AI-assisted","Lovable","Supabase"]}'::jsonb);
insert into public.entries (id, folder_slug, slug, title, org, role, period, location, kind, status, sort, body) values ('scribbleverse', 'builds', 'scribbleverse', 'Scribbleverse', null, 'Game Designer & Builder', null, null, 'build', 'live', 3, '{"summary":"A multiplayer ''exquisite corpse'' drawing game: players sketch sequential canvas segments blind, then reveal the whole creature together.","gap":"Party games are either fiercely competitive or intimidating to non-artists.","system":"Room-based play for 3 to 8 players with folded-edge guides, timed turns and a joint reveal.","result":"Live and playable with room codes and exportable canvases.","links":[{"label":"Play Scribbleverse","url":"https://scribblverse.lovable.app"}],"tags":["game design","real-time","canvas"]}'::jsonb);
insert into public.entries (id, folder_slug, slug, title, org, role, period, location, kind, status, sort, body) values ('style-dna', 'builds', 'style-dna', 'Style DNA', null, 'AI Designer & Builder', null, null, 'build', 'live', 4, '{"summary":"An AI jewellery discovery engine that reads saved inspiration photos and returns a curated wishlist with a reason for each match.","gap":"Shoppers can''t put their taste into a search box, and style quizzes give generic results.","system":"Upload 10-20 inspiration images; the model extracts colour harmony, metal finishes, geometry and design eras, then explains why each item fits.","result":"Live prototype with an upload queue, style profile and explainable recommendations.","links":[{"label":"Open Style DNA","url":"https://vestelle.lovable.app"}],"tags":["AI-assisted","e-commerce","vision"]}'::jsonb);
