insert into public.entries (id, folder_slug, slug, title, org, role, period, location, kind, status, sort, body) values ('medigrow', 'internships', 'medigrow', 'Business Development Intern', 'MediGrow', null, 'Feb''24 – Mar''24', 'Dubai (remote)', 'internship', null, 1, '{"summary":"Expanded the prospect pipeline for a healthcare marketing startup through targeted market research and outreach.","bullets":["Lead generation and market research via targeted data scraping and prospect identification.","Prepared and delivered proposals; handled coordination and scheduling.","LinkedIn outreach and networking to strengthen industry connections.","Supported discussions on business expansion strategies for the start-up."]}'::jsonb);
insert into public.entries (id, folder_slug, slug, title, org, role, period, location, kind, status, sort, body) values ('kloudmate', 'internships', 'kloudmate', 'Sales & Marketing Intern', 'KloudMate', null, 'Jan''23 – Dec''23', 'Bengaluru', 'internship', null, 2, '{"summary":"Built B2B prospect pipelines through targeted segmentation and outbound outreach.","bullets":["Identified prospects using tools like Intricately.","Cold outreach to decision-makers using Lusha and Apollo for B2B contact intelligence.","Kept records of client interactions and pipeline activity in HubSpot.","Market research and competitor analysis to support strategy."]}'::jsonb);
insert into public.entries (id, folder_slug, slug, title, org, role, period, location, kind, status, sort, body) values ('book-the-gap', 'academic-projects', 'book-the-gap', 'Book The Gap', 'Global Perspectives academic team project', 'Team Member', '2019', 'Bengaluru', 'project', null, 1, '{"summary":"Field research and educator interviews led the team to set up a multilingual library for Grades 1-5 at an underfunded government school.","gap":"Lack of prioritisation and funding for public education left a government school without reading resources.","system":"Used-book drives across school and apartment communities, resold to raise funds, then bought English, Kannada and Hindi books after talking to the headteacher; co-created a website and produced a documentary.","result":"A working library for Grades 1-5 and a documentary raising awareness of educational inequity.","links":[{"label":"Initiative website","url":"https://bookthegap.weebly.com/"},{"label":"Documentary","url":"https://www.youtube.com/watch?v=yPln43BsJro"}]}'::jsonb);
