insert into public.entries (id, folder_slug, slug, title, org, role, period, location, kind, status, sort, body) values ('sinchan', 'extra-curricular', 'sinchan-kurumutu', 'Sinchan NGO: Project Kurumutu', null, 'Volunteer', '2020 – 2022', 'Bengaluru', 'volunteering', null, 1, '{"summary":"Urban-rural peer-learning initiative for English and digital literacy.","gap":"Learners had gaps in conversational English and digital literacy, and rote methods led to drop-off.","system":"Designed peer-learning sessions with visual story pedagogy tied to learners’ lived experience, standardised session structures across cohorts, and onboarded volunteers.","result":"Programme scaled across cohorts; I led the rebranding of Project Lahanti as Kurumutu. Acknowledged in a published reflection by the project founder."}'::jsonb);
